"""Build a self-contained, offline EcoOrbit results website from bundled CSV/JSON."""
import base64, csv, json, html
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
def read_csv(path):
    with (ROOT/path).open(encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f))
def read_json(path): return json.loads((ROOT/path).read_text())
def picture(path):
    p=ROOT/path
    return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() if p.exists() else ''

def build(destination=None):
    data={
      'plumes':read_csv('results/real/methane/published_plume_results.csv'),
      'cases':read_csv('results/real/methane/case_status.csv'),
      'landfills':read_csv('data/landfill_sites.csv'),
      'emit_search':read_csv('results/real/landfill_gases/emit_search.csv') if (ROOT/'results/real/landfill_gases/emit_search.csv').exists() else [],
      'emit_candidates':read_csv('results/real/landfill_gases/emit_plume_candidates.csv') if (ROOT/'results/real/landfill_gases/emit_plume_candidates.csv').exists() else [],
      'oco':read_csv('results/real/landfill_gases/regional_xco2.csv') if (ROOT/'results/real/landfill_gases/regional_xco2.csv').exists() else [],
      'case_ch4':read_csv('results/real/methane/regional_ch4.csv') if (ROOT/'results/real/methane/regional_ch4.csv').exists() else [],
      'matches':read_csv('results/real/methane/plume_matches.csv') if (ROOT/'results/real/methane/plume_matches.csv').exists() else [],
      'methane':read_csv('results/real/methane/observed_us_regional_ch4.csv'),
      'sites':read_csv('results/real/classifier/factory_screening_results.csv'),
      'test':read_csv('results/real/classifier/all_city_test_predictions.csv'),
      'metrics':read_json('results/real/classifier/all_city_test_metrics.json'),
      'heat':read_csv('results/real/heat/site_heat.csv'),
      'pollutants':read_csv('results/real/pollutants/site_no2_so2.csv'),
      'aot':read_csv('results/real/aot/multicity_aot_comparison.csv'),
      'air':[],
      'wind':read_csv('results/real/wind_by_city.csv'),
      'land':read_csv('results/real/land/site_change.csv'),
      'green':read_json('results/real/green_reference_summary.json'),
      'carbon':read_json('results/real/carbon/status.json'),
      'images':{
        'classification':picture('results/real/hyperspectral_classification.png'),
        'factorymap':picture('results/real/classifier/factory_scores_map.png'),
        'greenmap':picture('results/real/green_reference_map.png'),
        'greencomparison':picture('results/real/green_reference_comparison.png'),
        'heat':picture('results/real/heat/site_heat.png'),
        'aot':picture('results/real/aot/multicity_aot.png'),
        'emit':picture('results/real/landfill_gases/emit_landfill_footprints.png')
      }
    }
    content=HTML.replace('/*__DATA__*/',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))
    from src.judge_pages import reframe
    content=reframe(content)
    from src.pixel_web import fragment
    card,script=fragment(ROOT)
    if card:
        content=content.replace('<!--PIXEL_PANEL-->',card)
        content=content.replace('</body>',script+'</body>')
    out=Path(destination) if destination else ROOT/'EcoOrbit_Results_Website.html'
    out.write_text(content,encoding='utf-8')
    return out

